Here is the root cause:
The bug arises from the lack of protection around the callback functions used to create inodes and dentries in the eventfs system. When `eventfs_remove_dir()` is called, it can free the events associated with a directory, leading to a situation where the callback may be invoked with stale data, potentially causing undefined behavior or crashes. This race condition occurs because the callback is not executed under a mutex lock, allowing concurrent access that can result in accessing freed memory.

Here is the patch:

 static struct dentry *eventfs_root_lookup(struct inode *dir,
 					  struct dentry *dentry,
 					  unsigned int flags)
 {
 	const struct file_operations *fops;
 	const struct eventfs_entry *entry;
 	struct eventfs_inode *ei_child;
 	struct tracefs_inode *ti;
 	struct eventfs_inode *ei;
 	struct dentry *ei_dentry = NULL;
 	struct dentry *ret = NULL;
 	const char *name = dentry->d_name.name;
 	bool created = false;
 	umode_t mode;
 	void *data;
 	int idx;
 	int i;
 	int r;

 	ti = get_tracefs(dir);
 	if (!(ti->flags & TRACEFS_EVENT_INODE))
 		return NULL;

 	/* Grab srcu to prevent the ei from going away */
 	idx = srcu_read_lock(&eventfs_srcu);

 	/*
 	 * Grab the eventfs_mutex to consistent value from ti->private.
 	 * This s
 	 */
 	mutex_lock(&eventfs_mutex);
 	ei = READ_ONCE(ti->private);
 	if (ei && !ei->is_freed)
 		ei_dentry = READ_ONCE(ei->dentry);
 	mutex_unlock(&eventfs_mutex);

 	if (!ei || !ei_dentry)
 		goto out;

 	data = ei->data;

 	list_for_each_entry_srcu(ei_child, &ei->children, list,
 				 srcu_read_lock_held(&eventfs_srcu)) {
 		if (strcmp(ei_child->name, name) != 0)
 			continue;
 		ret = simple_lookup(dir, dentry, flags);
 		create_dir_dentry(ei, ei_child, ei_dentry, true);
 		created = true;
 		break;
 	}

 	if (created)
 		goto out;

 	for (i = 0; i < ei->nr_entries; i++) {
 		entry = &ei->entries[i];
 		if (strcmp(name, entry->name) == 0) {
 			void *cdata = data;
-			r = entry->callback(name, &mode, &cdata, &fops);
+			mutex_lock(&eventfs_mutex);
+			/* If ei->is_freed, then the event itself may be too */
+			if (!ei->is_freed)
+				r = entry->callback(name, &mode, &cdata, &fops);
+			else
+				r = -1;
+			mutex_unlock(&eventfs_mutex);
 			if (r <= 0)
 				continue;
 			ret = simple_lookup(dir, dentry, flags);
 			create_file_dentry(ei, i, ei_dentry, name, mode, cdata,
 					   fops, true);
 			break;
 		}
 	}
  out:
 	srcu_read_unlock(&eventfs_srcu, idx);
 	return ret;
 }

  */
 static int dcache_dir_open_wrapper(struct inode *inode, struct file *file)
 {
 	const struct file_operations *fops;
 	const struct eventfs_entry *entry;
 	struct eventfs_inode *ei_child;
 	struct tracefs_inode *ti;
 	struct eventfs_inode *ei;
 	struct dentry_list *dlist;
 	struct dentry **dentries = NULL;
 	struct dentry *parent = file_dentry(file);
 	struct dentry *d;
 	struct inode *f_inode = file_inode(file);
 	const char *name = parent->d_name.name;
 	umode_t mode;
 	void *data;
 	int cnt = 0;
 	int idx;
 	int ret;
 	int i;
 	int r;

 	ti = get_tracefs(f_inode);
 	if (!(ti->flags & TRACEFS_EVENT_INODE))
 		return -EINVAL;

 	if (WARN_ON_ONCE(file->private_data))
 		return -EINVAL;

 	idx = srcu_read_lock(&eventfs_srcu);

 	mutex_lock(&eventfs_mutex);
 	ei = READ_ONCE(ti->private);
 	mutex_unlock(&eventfs_mutex);

 	if (!ei) {
 		srcu_read_unlock(&eventfs_srcu, idx);
 		return -EINVAL;
 	}


 	data = ei->data;

 	dlist = kmalloc(sizeof(*dlist), GFP_KERNEL);
 	if (!dlist) {
 		srcu_read_unlock(&eventfs_srcu, idx);
 		return -ENOMEM;
 	}

 	list_for_each_entry_srcu(ei_child, &ei->children, list,
 				 srcu_read_lock_held(&eventfs_srcu)) {
 		d = create_dir_dentry(ei, ei_child, parent, false);
 		if (d) {
 			ret = add_dentries(&dentries, d, cnt);
 			if (ret < 0)
 				break;
 			cnt++;
 		}
 	}

 	for (i = 0; i < ei->nr_entries; i++) {
 		void *cdata = data;
 		entry = &ei->entries[i];
 		name = entry->name;
-		r = entry->callback(name, &mode, &cdata, &fops);
+		mutex_lock(&eventfs_mutex);
+		/* If ei->is_freed, then the event itself may be too */
+		if (!ei->is_freed)
+			r = entry->callback(name, &mode, &cdata, &fops);
+		else
+			r = -1;
+		mutex_unlock(&eventfs_mutex);
 		if (r <= 0)
 			continue;
 		d = create_file_dentry(ei, i, parent, name, mode, cdata, fops, false);
 		if (d) {
 			ret = add_dentries(&dentries, d, cnt);
 			if (ret < 0)
 				break;
 			cnt++;
 		}
 	}
 	srcu_read_unlock(&eventfs_srcu, idx);
 	ret = dcache_dir_open(inode, file);

 	/*
 	 * dcache_dir_open() sets file->private_data to a dentry cursor.
 	 * Need to save that but also save all the dentries that were
 	 * opened by this function.
 	 */
 	dlist->cursor = file->private_data;
 	dlist->dentries = dentries;
 	file->private_data = dlist;
 	return ret;
 }

